H,W=30,24
grid=[[4]*W for _ in range(H)]
# upper source objects
for r,cells in [(6,[7,8]),(7,[6,7,8,9]),(8,[7,8])]:
    for c in cells: grid[r][c]=6
for r in [11,12]:
    for c in [3,4]: grid[r][c]=6
for r,cells in [(10,list(range(13,20))),(11,list(range(13,20))),(12,[13,14,18,19])]:
    for c in cells: grid[r][c]=3
# large panels
for r in range(16,24):
    grid[r][0]=grid[r][23]=7
    for c in range(1,23): grid[r][c]=6
for r in range(25,30):
    grid[r][0]=grid[r][23]=5
    for c in range(1,23): grid[r][c]=3
# Clear relocated source objects
for r in [6,7,8]:
    for c in range(W):
        if grid[r][c]==6: grid[r][c]=4
for r in [11,12]:
    for c in [3,4]: grid[r][c]=4
for r in [10,11,12]:
    for c in range(13,20): grid[r][c]=4
# Stamp the two 6 patterns at the bottom of the 6 panel; foreground becomes edge color 7
for r,cells in [(21,[7,8]),(22,[6,7,8,9]),(23,[7,8]),(22,[3,4]),(23,[3,4])]:
    for c in cells: grid[r][c]=7
# Stamp 3-object at bottom of 3 panel; foreground becomes edge color 5
for r in [27,28]:
    for c in [13,14,15,16,17,18,19]: grid[r][c]=5
for c in [13,14,18,19]: grid[29][c]=5
assert len(grid)==30 and all(len(row)==24 for row in grid)
for i,row in enumerate(grid): print(i, ' '.join(map(str,row)))
